contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 seedAmount, uint256 amount) public {
        require(amount <= seedAmount);
        c.mintToken(address(this), seedAmount); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        bool ok = c.transfer(address(this), amount); if (__ESBMC_reverted()) return;
        assert(ok && c.balanceOf(address(this)) == balBefore && c.totalSupply() == supplyBefore);
    }
    receive() external payable {}
